import { describe, it, expect, vi, beforeEach } from 'vitest'
import { TcLayerImpl } from '../src/background/tcLayer'
import type { BrowserApi } from '../src/models'
import { TEMP_CONTAINERS_EXTENSION_IDS } from '../src/constants'

function makeBrowserApi(): BrowserApi {
	return {
		menus: {
			create: vi.fn().mockResolvedValue(undefined),
			removeAll: vi.fn().mockResolvedValue(undefined),
			onClicked: { addListener: vi.fn() },
		},
		tabs: {
			create: vi.fn(),
			get: vi.fn(),
			discard: vi.fn().mockResolvedValue(undefined),
			onUpdated: { addListener: vi.fn() },
		},
		contextualIdentities: {
			query: vi.fn().mockResolvedValue([]),
			get: vi.fn(),
		},
		cookies: {
			getAll: vi.fn().mockResolvedValue([]),
			set: vi.fn().mockResolvedValue(null),
		},
		runtime: {
			sendMessage: vi.fn().mockResolvedValue(false),
			getURL: vi.fn((path: string) => `moz-extension://test/${path}`),
		},
		management: {
			get: vi.fn().mockRejectedValue(new Error('not installed')),
		},
	}
}

describe('TcLayerImpl', () => {
	let browserApi: BrowserApi

	beforeEach(() => {
		browserApi = makeBrowserApi()
	})

	it('isPresent() is false before initialize', () => {
		const layer = new TcLayerImpl({ browserApi })
		expect(layer.isPresent()).toBe(false)
	})

	it('initialize() finds the second known extension id when the first is not installed', async () => {
		const management = browserApi.management.get as ReturnType<typeof vi.fn>
		management.mockImplementation(async (id: string) => {
			if (id === TEMP_CONTAINERS_EXTENSION_IDS[1]) {
				return { id, name: 'TC+', enabled: true, type: 'extension' }
			}
			throw new Error('not installed')
		})

		const layer = new TcLayerImpl({ browserApi })
		await layer.initialize()

		expect(layer.isPresent()).toBe(true)
		expect(layer.extensionId).toBe(TEMP_CONTAINERS_EXTENSION_IDS[1])
	})

	it('initialize() leaves isPresent() false when neither extension is installed', async () => {
		const layer = new TcLayerImpl({ browserApi })
		await layer.initialize()
		expect(layer.isPresent()).toBe(false)
		expect(layer.extensionId).toBeNull()
	})

	it('isTempContainer() returns false when TC is not present, without calling sendMessage', async () => {
		const layer = new TcLayerImpl({ browserApi })
		await layer.initialize()
		const result = await layer.isTempContainer('firefox-container-1')
		expect(result).toBe(false)
		expect(browserApi.runtime.sendMessage).not.toHaveBeenCalled()
	})

	it('isTempContainer() delegates to the TC extension via sendMessage when present', async () => {
		const management = browserApi.management.get as ReturnType<typeof vi.fn>
		management.mockImplementation(async (id: string) => {
			if (id === TEMP_CONTAINERS_EXTENSION_IDS[0]) {
				return { id, name: 'TC', enabled: true, type: 'extension' }
			}
			throw new Error('not installed')
		})
		const sendMessage = browserApi.runtime.sendMessage as ReturnType<typeof vi.fn>
		sendMessage.mockResolvedValue(true)

		const layer = new TcLayerImpl({ browserApi })
		await layer.initialize()
		const result = await layer.isTempContainer('firefox-tmp-container-1')

