				return { id, name: 'TC', enabled: true, type: 'extension' }
			}
			throw new Error('not installed')
		})
		const sendMessage = browserApi.runtime.sendMessage as ReturnType<typeof vi.fn>
		sendMessage.mockResolvedValue({ id: 42, index: 3, cookieStoreId: 'firefox-tmp-container-9' })

		const layer = new TcLayerImpl({ browserApi })
		await layer.initialize()
		const tab = await layer.createTempContainer('https://example.com', 3, 1)

		expect(sendMessage).toHaveBeenCalledWith(
			TEMP_CONTAINERS_EXTENSION_IDS[0],
			{ method: 'createTabInTempContainer', url: 'https://example.com', active: true },
		)
		expect(tab).toEqual({ id: 42, index: 3, cookieStoreId: 'firefox-tmp-container-9' })
	})

	it('createTempContainer() throws when TC is not present', async () => {
		const layer = new TcLayerImpl({ browserApi })
		await layer.initialize()
		await expect(layer.createTempContainer('https://example.com', 0, 1)).rejects.toThrow()
	})
})

